require_once 'config.php'; if(!empty($_SESSION['admin_id'])){header('Location: kasir.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=trim($_POST['username']??'');$p=$_POST['password']??'';try{$st=db()->prepare('SELECT id,username,password_hash FROM admins WHERE username=? LIMIT 1');$st->execute([$u]);$a=$st->fetch();if($a&&password_verify($p,$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_username']=$a['username'];header('Location: kasir.php');exit;}else{$error='Username atau password salah.';}}catch(Throwable $e){$error='Database belum siap. Impor database.sql lalu buka setup-admin.php.';}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login Admin — Kasir Jawa</title><link rel="stylesheet" href="style.css"><style>body{min-height:100vh;display:grid;place-items:center;padding:20px}.login{width:min(430px,100%);background:var(--card);border:1px solid var(--line);border-top:5px solid var(--acc);border-radius:22px;padding:30px;box-shadow:0 20px 60px #3d130d20;animation:up .7s both}.login h1{color:var(--priD);margin-bottom:8px}.login p{color:var(--mute)}.login label{display:block;margin:14px 0 5px}.login button{width:100%;margin-top:20px}.password-wrap{position:relative;display:flex;align-items:center}.password-wrap input{width:100%;padding-right:52px;box-sizing:border-box}.password-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);display:grid;place-items:center;margin:0!important;width:36px!important;height:36px;padding:0;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--priD);cursor:pointer;transition:background .18s ease,border-color .18s ease}.password-toggle svg{width:19px;height:19px;display:block;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.password-toggle:hover{background:var(--accBg);border-color:var(--acc)}.password-toggle:focus-visible{outline:2px solid var(--acc);outline-offset:2px}.back-home{display:flex;align-items:center;justify-content:center;gap:9px;width:100%;box-sizing:border-box;margin-top:12px;padding:12px 16px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(135deg,#fffdf8,#f5efe3);color:var(--priD);font-size:14px;font-weight:700;text-decoration:none;transition:transform .18s ease,background .18s ease,border-color .18s ease,box-shadow .18s ease}.back-home:hover{background:var(--accBg);border-color:var(--acc);box-shadow:0 6px 16px rgba(61,19,13,.10);transform:translateY(-2px)}.back-home:active{transform:translateY(0)}.back-home:focus-visible{outline:3px solid var(--acc);outline-offset:3px}.back-home .back-arrow{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--accBg);color:var(--priD);font-size:17px;line-height:1}.err{background:#fff0ed;color:#a1261d;padding:10px;border-radius:8px}@keyframes up{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}</style></head><body><form class="login" method="post"><h1>Login Admin</h1><p>Masuk untuk mengelola kasir dan laporan pendapatan restoran.</p><?php if($error):?><div class="err"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><label>Username</label><input name="username" required autocomplete="username"><label for="admin-password">Password</label><div class="password-wrap"><input id="admin-password" type="password" name="password" required autocomplete="current-password"><button class="password-toggle" type="button" id="toggle-password" aria-label="Tampilkan password" title="Tampilkan password" aria-controls="admin-password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg></button></div><button class="pri" type="submit">Masuk ke Dashboard</button><a class="back-home" href="index.php"><span class="back-arrow" aria-hidden="true"></span><span>Kembali ke beranda</span></a></form><script>const passwordInput=document.getElementById("admin-password");const passwordToggle=document.getElementById("toggle-password");const eyeIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/></svg>';const eyeOffIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 6.2A10.8 10.8 0 0 1 12 6c6.1 0 9.5 6 9.5 6a15.6 15.6 0 0 1-3.1 3.6M6.2 6.3C3.8 8 2.5 12 2.5 12s3.4 6 9.5 6c1.1 0 2.1-.2 3-.6"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';passwordToggle.addEventListener("click",function(){const show=passwordInput.type==="password";passwordInput.type=show?"text":"password";passwordToggle.innerHTML=show?eyeOffIcon:eyeIcon;const label=show?"Sembunyikan password":"Tampilkan password";passwordToggle.setAttribute("aria-label",label);passwordToggle.setAttribute("title",label);passwordToggle.setAttribute("aria-pressed",String(show));passwordInput.focus();});</script></body></html>